        if (maxAPICalls) |maxAPICalls_val| {
            const maxAPICalls_str = try std.fmt.allocPrint(self.arena, "{d}", .{maxAPICalls_val});
            cur = try cur.arg(self.arena, "maxAPICalls", .{ .eager = maxAPICalls_str });
        }
        return .{
            .allocator = self.allocator,
            .arena = self.arena,
            .selection = cur,
            .gql = self.gql,
        };
    }

